const models=[{name:'iPhone 18 Pro',image:'pro',copy:'For the big ideas. And the smallest details.',colors:['#57303a','#cbdde6','#dddcd8','#353535'],detail:'Explore the Pro collection, with a focus on creative photography and performance. Confirm storage, finish, price, and availability with Darlin.'},{name:'iPhone Air',image:'air',copy:'A lighter touch. A beautiful way to do more.',colors:['#cbdfe8','#e9e2cf','#ecebe7','#252525'],detail:'Explore a light, slim iPhone design. Ask Darlin about available finishes and storage options before choosing your model.'},{name:'iPhone 17',image:'standard',copy:'Everyday magic. In a colour that feels like you.',colors:['#b9afd2','#bccbb4','#d1dfeb','#eeeae2','#353535'],detail:'Explore the everyday iPhone collection and find a finish that suits your style. Pricing and available configurations require confirmation.'}];
let saved;try{saved=JSON.parse(localStorage.getItem('darlin-shortlist')||'[]')}catch{saved=[]}if(!Array.isArray(saved))saved=[];saved=saved.filter(x=>[...models.map(m=>m.name),'Cases & charging','AirTag'].includes(x));const dialog=document.querySelector('#dialog'),content=document.querySelector('#dialog-content');
function render(){document.querySelector('#products').innerHTML=models.map((m,i)=>`<article class="product reveal"><div class="product-photo"><img src="assets/${m.image}.jpg" alt="${m.name} front and back" loading="lazy"></div><div class="product-content"><div class="dots" aria-label="Example finishes">${m.colors.map(c=>`<i style="background:${c}"></i>`).join('')}</div><h3>${m.name}</h3><p>${m.copy}</p><div class="product-actions"><button class="text-button" data-detail="${i}">Take a closer look ↗</button><button class="add" data-save="${m.name}">${saved.includes(m.name)?'Saved ✓':'Shortlist +'}</button></div></div></article>`).join('');document.querySelector('#count').textContent=saved.length;document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});render();
function open(html){content.innerHTML=html;dialog.showModal()}function persist(){try{localStorage.setItem('darlin-shortlist',JSON.stringify(saved))}catch{}render()}function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
document.addEventListener('click',e=>{const detail=e.target.closest('[data-detail]'),save=e.target.closest('[data-save]'),acc=e.target.closest('[data-accessory]');if(detail){const m=models[Number(detail.dataset.detail)];open(`<p class="eyebrow">A CLOSER LOOK</p><h2>${m.name}</h2><img src="assets/${m.image}.jpg" alt="${m.name}"><p>${m.detail}</p><button class="button" data-save="${m.name}">${saved.includes(m.name)?'Remove from shortlist':'Add to shortlist +'}</button>`)}if(save){const name=save.dataset.save;const exists=saved.includes(name);saved=exists?saved.filter(x=>x!==name):[...saved,name];persist();save.textContent=exists?'Add to shortlist +':'Remove from shortlist';toast(exists?'Removed from your shortlist':'Added to your shortlist')}if(acc){const name=acc.dataset.accessory;open(`<p class="eyebrow">THE FINISHING TOUCH</p><h2>${name}</h2><p>${name==='AirTag'?'Explore AirTag and key ring accessories for the things you take everywhere.':'Find a case, charging setup, or MagSafe accessory to complement your iPhone. Confirm compatibility with your exact model.'} Ask Darlin to confirm available products and prices.</p><button class="button" data-save="${name}">${saved.includes(name)?'Remove from shortlist':'Add to shortlist +'}</button>`)}});
document.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close()}});
document.querySelector('#compare').onclick=()=>open(`<p class="eyebrow">THE COLLECTION AT A GLANCE</p><h2>Which one feels like you?</h2><div class="compare-grid">${models.map(m=>`<article><img src="assets/${m.image}.jpg" alt="${m.name}"><h3>${m.name}</h3><p>${m.copy}</p><button class="text-button" data-save="${m.name}">${saved.includes(m.name)?'Remove from shortlist':'Shortlist +'}</button></article>`).join('')}</div><p>Ask Darlin for exact specifications, available configurations, and current prices.</p>`);
document.querySelector('#open-saved').onclick=()=>{open(`<p class="eyebrow">YOUR FAVOURITES, TOGETHER</p><h2>Your shortlist.</h2>${saved.length?saved.map(n=>`<div class="short-row"><span>${n}</span><button data-remove="${n}">Remove ×</button></div>`).join('')+'<p>Copy this enquiry and share it with Darlin through your preferred contact channel.</p><textarea aria-label="Your enquiry" readonly></textarea><button class="button" id="copy">Copy enquiry ↗</button>':'<p>A fresh start. Explore the collection and save anything that catches your eye.</p><button class="button" id="explore">Explore iPhone ↗</button>'}`);if(saved.length){content.querySelector('textarea').value='Hello Darlin! I’m interested in '+saved.join(', ')+'. Please confirm availability, finishes, storage options, and current prices.';content.querySelector('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(content.querySelector('textarea').value);toast('Enquiry copied')}catch{content.querySelector('textarea').select();toast('Select and copy your enquiry')}}}else content.querySelector('#explore').onclick=()=>{dialog.close();location.hash='lineup'};content.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{saved=saved.filter(n=>n!==b.dataset.remove);persist();dialog.close();document.querySelector('#open-saved').click()})};
document.querySelector('#motion').onclick=e=>{const paused=document.querySelector('.hero').classList.toggle('paused');e.currentTarget.textContent=paused?'▶':'Ⅱ';e.currentTarget.setAttribute('aria-pressed',paused);e.currentTarget.setAttribute('aria-label',paused?'Resume gentle hero motion':'Pause gentle hero motion')};document.querySelector('.menu').onclick=e=>{const expanded=document.querySelector('nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',expanded)};document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{document.querySelector('nav').classList.remove('open');document.querySelector('.menu').setAttribute('aria-expanded','false')});
